import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.component.textfield.TextArea;
import com.vaadin.flow.data.binder.Binder;
import com.vaadin.flow.router.BeforeLeaveEvent;
import com.vaadin.flow.router.BeforeLeaveObserver;
import com.vaadin.flow.router.Route;
import org.springframework.beans.factory.annotation.Autowired;

@Route("contact")
public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
    private final MessageService messageService;
    private TextField nameField;
    private EmailField emailField;
    private TextField phoneField;
    private TextArea messageField;
    private Button sendButton;
    private Grid<Message> grid;
    private Binder<FormData> binder;

    @Autowired
    public ContactView(MessageService messageService) {
        this.messageService = messageService;
        initializeLayout();
        refreshGrid();
    }

    private void initializeLayout() {
        add(new H1("Contact"));

        Anchor aboutLink = new Anchor("about", "About");
        add(aboutLink);

        nameField = new TextField("Name");
        emailField = new EmailField("Email");
        phoneField = new TextField("Phone");
        messageField = new TextArea("Message");
        messageField.setHeight("150px");

        sendButton = new Button("Send");
        sendButton.setEnabled(true);

        FormData formData = new FormData();
        binder = new Binder<>(FormData.class);
        binder.bind(nameField, "name");
        binder.bind(emailField, "email");
        binder.bind(phoneField, "phone");
        binder.bind(messageField, "text");

        FormLayout form = new FormLayout();
        form.add(nameField, emailField, phoneField, messageField);

        nameField.addValueChangeListener(e -> sendButton.setEnabled(true));
        emailField.addValueChangeListener(e -> sendButton.setEnabled(true));
        phoneField.addValueChangeListener(e -> sendButton.setEnabled(true));
        messageField.addValueChangeListener(e -> sendButton.setEnabled(true));

        sendButton.addClickListener(e -> handleSend());
        sendButton.addClickShortcut(Key.ENTER);

        add(form);
        add(sendButton);

        grid = new Grid<>(Message.class, false);
        grid.addColumn(Message::getName).setHeader("Name");
        grid.addColumn(Message::getText).setHeader("Message");
        grid.setItems(messageService.getMessages());

        add(grid);
    }

    private void handleSend() {
        FormData formData = new FormData();
        binder.writeBeanIfValid(formData);

        if (!validateForm(formData)) {
            return;
        }

        Message message = new Message(
            formData.getName(),
            formData.getEmail(),
            formData.getPhone(),
            formData.getText()
        );

        messageService.addMessage(message);
        Notification.show("Message sent");

        nameField.clear();
        emailField.clear();
        phoneField.clear();
        messageField.clear();

